import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 totalInternalBalances;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 seed) public {
        // Bound amount to reasonable range and avoid zero
        amount = bound(amount, 1, 1000 ether);
        // Derive a user address from seed so the fuzzer can explore different callers
        address user = address(uint160(seed >> 96));
        vm.assume(user != address(0) && user != address(c));

        // Setup: fund the user and have them deposit so c has Ether and a balance record
        vm.deal(user, amount);
        vm.prank(user);
        c.deposit{value: amount}();

        // The invariant: contract's Ether balance must be >= sum of all internal balances.
        // The only internal balance is the user's, since no other deposits occurred.
        // We compute totalInternalBalances from the user's balance after deposit.
        totalInternalBalances = c.balances(user);
        uint256 contractBalanceBefore = address(c).balance;

        // Trigger the mutation-critical path: withdraw
        vm.prank(user);
        c.withdraw(amount);

        // After withdraw, in the correct contract, Ether was sent, balances reduced,
        // so contractBalance = totalInternalBalances (both = 0).
        // In the mutant, balances reduced but no Ether sent, so contract balance remains
        // greater than totalInternalBalances.
        assertTrue(address(c).balance >= c.balances(user));
    }
}

