import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 extraDeposit) public {
        // Restrict to feasible amounts
        amount = bound(amount, 1, 100 ether);
        extraDeposit = bound(extraDeposit, 0, 100 ether);

        // Deploy a reverting helper to act as the caller
        Reverter reverter = new Reverter();
        address caller = address(reverter);

        // Fund caller and deposit into c
        vm.deal(caller, amount + extraDeposit);
        vm.prank(caller);
        c.deposit{value: amount}();

        // Record balances before withdrawal
        uint256 balBeforeCaller = c.balances(caller);
        uint256 balBeforeContract = address(c).balance;

        // Attempt withdrawal via the reverting helper (which will revert on transfer)
        vm.prank(caller);
        reverter.withdrawToRevert(address(c), amount);

        // After the revert, invariant: caller balance + contract balance == old caller balance + old contract balance
        uint256 balAfterCaller = c.balances(caller);
        uint256 balAfterContract = address(c).balance;
        assertTrue(balAfterCaller + balAfterContract == balBeforeCaller + balBeforeContract);
    }
}

contract Reverter {
    function withdrawToRevert(address target, uint256 amount) external {
        // This call will attempt a transfer to this contract, which will revert in receive()
        C(target).withdraw(amount);
    }
    receive() external payable {
        revert("revert on receive");
    }
}

