pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, uint8 reenterDepth) public {
        // Bound amounts to feasible domain and ensure reentry depth limited
        depositAmount = bound(depositAmount, 1, 100 ether);
        withdrawAmount = bound(withdrawAmount, 1, 100 ether);
        vm.assume(reenterDepth <= 3);

        // Deploy reentrant attacker contract
        ReentrantAttacker attacker = new ReentrantAttacker(c, reenterDepth);

        // Fund attacker and deposit
        vm.deal(address(attacker), depositAmount);
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        // Record balance before withdrawal
        uint256 balBefore = address(attacker).balance;

        // Initiate withdrawal through attacker
        vm.prank(address(attacker));
        attacker.startWithdraw(withdrawAmount);

        // Verify invariant: the attacker's current ETH balance minus the initial ETH balance
        // must equal the withdrawn amount (since deposit was already made).
        // The bug reduces balance before transfer, so if reentrant call re-withdraws,
        // balance can go negative relative to the invariant.
        uint256 balAfter = address(attacker).balance;
        assertTrue(balAfter - balBefore == withdrawAmount);
    }
}

contract ReentrantAttacker {
    C public c;
    uint8 depth;
    uint8 maxDepth;
    uint256 amount;

    constructor(C _c, uint8 _maxDepth) {
        c = _c;
        maxDepth = _maxDepth;
    }

    function startWithdraw(uint256 _amount) external {
        depth = 0;
        amount = _amount;
        c.withdraw(_amount);
    }

    receive() external payable {
        if (depth < maxDepth) {
            depth++;
            c.withdraw(amount);
        }
    }
}

