        RevertingRecipient revertingHelper = new RevertingRecipient();
        address caller = makeAddr("caller");
        {
            // Use seed to select another address (not the caller) as depositor,
            // so the caller gets funded indirectly via refund or explicit deposit.
            // We just need the caller to have a balance; simplest: caller deposits.
            vm.deal(caller, amount);
            vm.prank(caller);
            c.deposit{value: amount}();
        }

        // Record caller's balance before attempted withdrawal
        uint256 balanceBefore = c.balances(caller);

        // Attempt withdrawal to the reverting helper; this must fail
        vm.prank(caller);
        try c.withdraw(amount) {
            // Should not succeed against the reverting helper
            revert("withdraw unexpectedly succeeded to reverting recipient");
        } catch {
            // Expected failure
        }

        // Property: after a failed withdrawal, the caller's balance must be unchanged
        uint256 balanceAfter = c.balances(caller);
        assertTrue(balanceAfter == balanceBefore, "balance changed after failed withdrawal");
    }
